-- Speglar det som lades på databasen 2026-09-16 via apply_migration i sjutton delar:
--   kq2_order_code_from_catalogue_part_01  (familjen kq2 in, backup, schema, familjens rad, parametrar)
--   kq2_order_code_from_catalogue_part_02  (värdelista, rensning av regler)
--   kq2_order_code_from_catalogue_part_03–16  (regler 1–278 i satser om 20, dokumentkarta, produkterna KQ2H06-00A, KQ2H08-00A, KQ2L06-01A, KQ2L08-02A)
--   kq2_order_code_from_catalogue_part_17  (produkterna KQ2H04-M5A, KQ2H06-01AS, KQ2H08-02AS, KQ2L06-01AS, KQ2T06-00A; max_pressure_bar bort)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts kq2):
--   regler  278  md5 c67ca3fddc0f4ad376507c90098254de   villkor 2a4a0c1bbfdce00553a46ad63d0cafb7
--   värden  77   md5 1849f38d0070a156e8c73e913a943df4
--   schema       md5 d32116530e025f636848f3cc316aaeea
-- Verifierat live: /sv/configurator/kq2 bygger KQ2H06-01AS1 (nyckelns exempel sida 6), KQ2H06-00A och
-- KQ2N04-99; stoppar KQ2H06-04AS (ø6 finns inte med R1/2), KQ2H23-M3A (M3 bara rostfritt) och
-- KQ2LU04-01NP1 (LU bara rund knapp).
--
-- KQ2: beställnyckeln enligt SMC One-touch Fittings KQ2 Series (CAT.ES50-37D, sida 6 och 102).
-- GENERERAD ur src/lib/catalog/kq2.ts och kq2-models.ts -- redigera inte för hand.
--
-- Ny familj kq2 i kategorin fitting: KQ2{typ}{slang}-{port}{material}{tätning}{knapp},
-- t.ex. KQ2H06-01AS1 (nyckelns exempel sida 6) och KQ2H06-01AS (sida 102).
-- 32 kopplingstyper, åtta metriska slangmått, 31 portar, tre material, två
-- tätningar och oval knapp; 1 540 modellnummer ur måttabellerna styr vilka
-- kombinationer som finns. Tumslangens kapitel är inte med.
--
-- De nio produktraderna får SMC-prefix, den nya nyckelns materialbokstav
-- (KQ2H06-01S -> KQ2H06-01AS, KQ2T06-00 -> KQ2T06-00A) och rätt gänga
-- (portkoden 01 är R1/8, inte G1/8).

begin;


insert into configurator_families (slug, name, title, description, category_slug)
values ('kq2', 'KQ2', 'KQ2', '', 'fitting')
on conflict (slug) do update set name = excluded.name;


create schema if not exists backup;
create table if not exists backup.kq2_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'kq2'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'kq2'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'kq2';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-KQ2-V1', '{"version":"1.0","steps":[{"id":"type","step":1,"title_sv":"Kopplingstyp","title_en":"Fitting type","required":true,"type":"single_select","options":[{"v":"H","label":"Rak: hankoppling (gänga), rak skarv (00) eller reducerad rak (slangmått)"},{"v":"S","label":"Rak hankoppling med insexfattning"},{"v":"F","label":"Rak honkoppling (Rc, M, G)"},{"v":"L","label":"Vinkel: hankoppling, vinkelskarv (00), instick (99) eller reducerad vinkel"},{"v":"LU","label":"Grenvinkel: han (gänga) eller skarv (00); bara rund knapp"},{"v":"K","label":"45° hankoppling"},{"v":"V","label":"Svivelvinkel, han"},{"v":"VS","label":"Svivelvinkel, han, med insexfattning"},{"v":"VF","label":"Svivelvinkel, hon"},{"v":"LF","label":"Vinkel honkoppling (Rc, M)"},{"v":"VD","label":"Dubbel svivelvinkel, han"},{"v":"VT","label":"Trippel svivelvinkel, han"},{"v":"Z","label":"Gren-svivelvinkel, han; bara rund knapp"},{"v":"ZF","label":"Gren-svivelvinkel, hon; bara rund knapp"},{"v":"ZD","label":"Dubbel gren-svivelvinkel, han; bara rund knapp"},{"v":"ZT","label":"Trippel gren-svivelvinkel, han; bara rund knapp"},{"v":"W","label":"Förlängd vinkel: han (gänga) eller instick (99)"},{"v":"T","label":"T: han-T (gänga), T-skarv (00) eller reducerad T (slangmått)"},{"v":"Y","label":"Han-T i löpriktningen (run tee)"},{"v":"D","label":"Delta: han-delta (gänga) eller delta-skarv (00)"},{"v":"TW","label":"Korsskarv (00)"},{"v":"TX","label":"Reducerad korsskarv, typ X (slangmått)"},{"v":"TY","label":"Reducerad korsskarv, typ Y (slangmått)"},{"v":"U","label":"Y: han-Y (gänga), Y-skarv (00), instick-Y (99) eller reducerad Y-skarv; bara rund knapp"},{"v":"UD","label":"Reducerad gren-Y; bara rund knapp"},{"v":"X","label":"Reducerad instick-Y; bara rund knapp"},{"v":"XD","label":"Dubbel instick-Y; bara rund knapp"},{"v":"R","label":"Instick-reducering (slangmått)"},{"v":"E","label":"Skottgenomföring: skarv (00) eller hankoppling (Rc/G)"},{"v":"LE","label":"Skottgenomföring, vinkelskarv (00)"},{"v":"N","label":"Nippel (99), reducernippel (slangmått) eller adapter (gänga); bara rund knapp"},{"v":"C","label":"Slanglock (00)"}]},{"id":"tube","step":2,"title_sv":"Slangens ytterdiameter","title_en":"Tubing O.D.","required":true,"type":"single_select","options":[{"v":"02","label":"ø2 mm"},{"v":"23","label":"ø3,2 mm"},{"v":"04","label":"ø4 mm"},{"v":"06","label":"ø6 mm"},{"v":"08","label":"ø8 mm"},{"v":"10","label":"ø10 mm"},{"v":"12","label":"ø12 mm"},{"v":"16","label":"ø16 mm"}]},{"id":"port","step":3,"title_sv":"Port: gänga, slang på andra sidan, skottgenomföring eller nippel","title_en":"Port: thread, tubing on the other side, bulkhead or nipple","required":true,"type":"single_select","options":[{"v":"M3","label":"M3 x 0,5 med gasket (bara rostfritt G)"},{"v":"M5","label":"M5 x 0,8 med gasket"},{"v":"M6","label":"M6 x 1,0 med gasket"},{"v":"01","label":"R1/8 (han) / Rc1/8 (hon)"},{"v":"02","label":"R1/4 (han) / Rc1/4 (hon)"},{"v":"03","label":"R3/8 (han) / Rc3/8 (hon)"},{"v":"04","label":"R1/2 (han) / Rc1/2 (hon)"},{"v":"G01","label":"G1/8 med plantätning"},{"v":"G02","label":"G1/4 med plantätning"},{"v":"G03","label":"G3/8 med plantätning"},{"v":"G04","label":"G1/2 med plantätning"},{"v":"U01","label":"Uni 1/8 (passar Rc, G, NPT, NPTF) med gasket"},{"v":"U02","label":"Uni 1/4 med gasket"},{"v":"U03","label":"Uni 3/8 med gasket"},{"v":"U04","label":"Uni 1/2 med gasket"},{"v":"00A","label":"Slang på båda sidor, samma mått (skarv)"},{"v":"99A","label":"Instick (rörände), samma mått"},{"v":"23A","label":"Slang ø3,2 på andra sidan (reducering)"},{"v":"04A","label":"Slang ø4 på andra sidan (reducering)"},{"v":"06A","label":"Slang ø6 på andra sidan (reducering)"},{"v":"08A","label":"Slang ø8 på andra sidan (reducering)"},{"v":"10A","label":"Slang ø10 på andra sidan (reducering)"},{"v":"12A","label":"Slang ø12 på andra sidan (reducering)"},{"v":"16A","label":"Slang ø16 på andra sidan (reducering)"},{"v":"00","label":"Skottgenomföring med slang på båda sidor (E, LE)"},{"v":"99","label":"Nippel, samma mått (N)"},{"v":"06","label":"Reducernippel till ø6 (N)"},{"v":"08","label":"Reducernippel till ø8 (N)"},{"v":"10","label":"Reducernippel till ø10 (N)"},{"v":"12","label":"Reducernippel till ø12 (N)"},{"v":"16","label":"Reducernippel till ø16 (N)"}]},{"id":"material","step":4,"title_sv":"Gängmaterial (gängade kopplingar och skottgenomföringar)","title_en":"Thread material (threaded fittings and bulkheads)","required":false,"type":"single_select","options":[{"v":"A","label":"Mässing"},{"v":"N","label":"Mässing, kemiskt förnicklad"},{"v":"G","label":"Rostfritt stål 303 (bara M3)"}]},{"id":"seal","step":5,"title_sv":"Tätning på R-gängan (standard är utan)","title_en":"Seal on the R thread (none is standard)","required":false,"type":"single_select","options":[{"v":"S","label":"Tätningsmedel på R-gängan"},{"v":"P","label":"Plantätning på R-gängan (face seal)"}]},{"id":"button","step":6,"title_sv":"Frigöringsknapp (standard är rund)","title_en":"Release button (round is standard)","required":false,"type":"single_select","options":[{"v":"1","label":"Oval frigöringsknapp (ø3,2, ø4, ø6; standard är rund)"}]}]}'::jsonb,
        'SMC KQ2 snabbkoppling, metrisk slang', 'SMC KQ2 One-touch fitting, metric tubing', 'fitting')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Snabbkopplingar KQ2 för slang ø2–ø16: gängade (M, R/Rc, G, Uni), skarvar, instick, reduceringar, nipplar och slanglock',
  description = 'SMC KQ2 One-touch fittings for metric tubing ø2–ø16: 32 body types (male/female connectors, elbows, universal elbows, tees, run tees, Y, delta, cross, bulkheads, reducers, nipples, tube caps), threads M3/M5/M6 with gasket, R/Rc 1/8–1/2 with sealant (S) or face seal (P), G 1/8–1/2 with face seal, Uni 1/8–1/2 with gasket, brass (A), nickel-plated brass (N) or stainless 303 (G, M3 only), round or oval (1) release button. −100 kPa to 1 MPa, −5…60 °C. Inch tubing, the Clean series (10-) and made-to-order (-X) are not included.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'KQ2{type}{tube}-{port}{material}{seal}{button}',
  rules_schema_id = 'SCHEMA-KQ2-V1'
where slug = 'kq2';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'kq2';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'kq2';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"type","label":"Kopplingstyp","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"tube","label":"Slangens ytterdiameter","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"port","label":"Port: gänga, slang på andra sidan, skottgenomföring eller nippel","param_type":"select","sort_order":3,"required":true,"min_value":null,"max_value":null},{"param_key":"material","label":"Gängmaterial (gängade kopplingar och skottgenomföringar)","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"seal","label":"Tätning på R-gängan (standard är utan)","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"button","label":"Frigöringsknapp (standard är rund)","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'kq2';

