from jsonb_to_recordset('[{"param_key":"type","code":"H","label":"Rak: hankoppling (gänga), rak skarv (00) eller reducerad rak (slangmått)","sort_order":0},{"param_key":"type","code":"S","label":"Rak hankoppling med insexfattning","sort_order":1},{"param_key":"type","code":"F","label":"Rak honkoppling (Rc, M, G)","sort_order":2},{"param_key":"type","code":"L","label":"Vinkel: hankoppling, vinkelskarv (00), instick (99) eller reducerad vinkel","sort_order":3},{"param_key":"type","code":"LU","label":"Grenvinkel: han (gänga) eller skarv (00); bara rund knapp","sort_order":4},{"param_key":"type","code":"K","label":"45° hankoppling","sort_order":5},{"param_key":"type","code":"V","label":"Svivelvinkel, han","sort_order":6},{"param_key":"type","code":"VS","label":"Svivelvinkel, han, med insexfattning","sort_order":7},{"param_key":"type","code":"VF","label":"Svivelvinkel, hon","sort_order":8},{"param_key":"type","code":"LF","label":"Vinkel honkoppling (Rc, M)","sort_order":9},{"param_key":"type","code":"VD","label":"Dubbel svivelvinkel, han","sort_order":10},{"param_key":"type","code":"VT","label":"Trippel svivelvinkel, han","sort_order":11},{"param_key":"type","code":"Z","label":"Gren-svivelvinkel, han; bara rund knapp","sort_order":12},{"param_key":"type","code":"ZF","label":"Gren-svivelvinkel, hon; bara rund knapp","sort_order":13},{"param_key":"type","code":"ZD","label":"Dubbel gren-svivelvinkel, han; bara rund knapp","sort_order":14},{"param_key":"type","code":"ZT","label":"Trippel gren-svivelvinkel, han; bara rund knapp","sort_order":15},{"param_key":"type","code":"W","label":"Förlängd vinkel: han (gänga) eller instick (99)","sort_order":16},{"param_key":"type","code":"T","label":"T: han-T (gänga), T-skarv (00) eller reducerad T (slangmått)","sort_order":17},{"param_key":"type","code":"Y","label":"Han-T i löpriktningen (run tee)","sort_order":18},{"param_key":"type","code":"D","label":"Delta: han-delta (gänga) eller delta-skarv (00)","sort_order":19},{"param_key":"type","code":"TW","label":"Korsskarv (00)","sort_order":20},{"param_key":"type","code":"TX","label":"Reducerad korsskarv, typ X (slangmått)","sort_order":21},{"param_key":"type","code":"TY","label":"Reducerad korsskarv, typ Y (slangmått)","sort_order":22},{"param_key":"type","code":"U","label":"Y: han-Y (gänga), Y-skarv (00), instick-Y (99) eller reducerad Y-skarv; bara rund knapp","sort_order":23},{"param_key":"type","code":"UD","label":"Reducerad gren-Y; bara rund knapp","sort_order":24},{"param_key":"type","code":"X","label":"Reducerad instick-Y; bara rund knapp","sort_order":25},{"param_key":"type","code":"XD","label":"Dubbel instick-Y; bara rund knapp","sort_order":26},{"param_key":"type","code":"R","label":"Instick-reducering (slangmått)","sort_order":27},{"param_key":"type","code":"E","label":"Skottgenomföring: skarv (00) eller hankoppling (Rc/G)","sort_order":28},{"param_key":"type","code":"LE","label":"Skottgenomföring, vinkelskarv (00)","sort_order":29},{"param_key":"type","code":"N","label":"Nippel (99), reducernippel (slangmått) eller adapter (gänga); bara rund knapp","sort_order":30},{"param_key":"type","code":"C","label":"Slanglock (00)","sort_order":31},{"param_key":"tube","code":"02","label":"ø2 mm","sort_order":0},{"param_key":"tube","code":"23","label":"ø3,2 mm","sort_order":1},{"param_key":"tube","code":"04","label":"ø4 mm","sort_order":2},{"param_key":"tube","code":"06","label":"ø6 mm","sort_order":3},{"param_key":"tube","code":"08","label":"ø8 mm","sort_order":4},{"param_key":"tube","code":"10","label":"ø10 mm","sort_order":5},{"param_key":"tube","code":"12","label":"ø12 mm","sort_order":6},{"param_key":"tube","code":"16","label":"ø16 mm","sort_order":7},{"param_key":"port","code":"M3","label":"M3 x 0,5 med gasket (bara rostfritt G)","sort_order":0},{"param_key":"port","code":"M5","label":"M5 x 0,8 med gasket","sort_order":1},{"param_key":"port","code":"M6","label":"M6 x 1,0 med gasket","sort_order":2},{"param_key":"port","code":"01","label":"R1/8 (han) / Rc1/8 (hon)","sort_order":3},{"param_key":"port","code":"02","label":"R1/4 (han) / Rc1/4 (hon)","sort_order":4},{"param_key":"port","code":"03","label":"R3/8 (han) / Rc3/8 (hon)","sort_order":5},{"param_key":"port","code":"04","label":"R1/2 (han) / Rc1/2 (hon)","sort_order":6},{"param_key":"port","code":"G01","label":"G1/8 med plantätning","sort_order":7},{"param_key":"port","code":"G02","label":"G1/4 med plantätning","sort_order":8},{"param_key":"port","code":"G03","label":"G3/8 med plantätning","sort_order":9},{"param_key":"port","code":"G04","label":"G1/2 med plantätning","sort_order":10},{"param_key":"port","code":"U01","label":"Uni 1/8 (passar Rc, G, NPT, NPTF) med gasket","sort_order":11},{"param_key":"port","code":"U02","label":"Uni 1/4 med gasket","sort_order":12},{"param_key":"port","code":"U03","label":"Uni 3/8 med gasket","sort_order":13},{"param_key":"port","code":"U04","label":"Uni 1/2 med gasket","sort_order":14},{"param_key":"port","code":"00A","label":"Slang på båda sidor, samma mått (skarv)","sort_order":15},{"param_key":"port","code":"99A","label":"Instick (rörände), samma mått","sort_order":16},{"param_key":"port","code":"23A","label":"Slang ø3,2 på andra sidan (reducering)","sort_order":17},{"param_key":"port","code":"04A","label":"Slang ø4 på andra sidan (reducering)","sort_order":18},{"param_key":"port","code":"06A","label":"Slang ø6 på andra sidan (reducering)","sort_order":19},{"param_key":"port","code":"08A","label":"Slang ø8 på andra sidan (reducering)","sort_order":20},{"param_key":"port","code":"10A","label":"Slang ø10 på andra sidan (reducering)","sort_order":21},{"param_key":"port","code":"12A","label":"Slang ø12 på andra sidan (reducering)","sort_order":22},{"param_key":"port","code":"16A","label":"Slang ø16 på andra sidan (reducering)","sort_order":23},{"param_key":"port","code":"00","label":"Skottgenomföring med slang på båda sidor (E, LE)","sort_order":24},{"param_key":"port","code":"99","label":"Nippel, samma mått (N)","sort_order":25},{"param_key":"port","code":"06","label":"Reducernippel till ø6 (N)","sort_order":26},{"param_key":"port","code":"08","label":"Reducernippel till ø8 (N)","sort_order":27},{"param_key":"port","code":"10","label":"Reducernippel till ø10 (N)","sort_order":28},{"param_key":"port","code":"12","label":"Reducernippel till ø12 (N)","sort_order":29},{"param_key":"port","code":"16","label":"Reducernippel till ø16 (N)","sort_order":30},{"param_key":"material","code":"A","label":"Mässing","sort_order":0},{"param_key":"material","code":"N","label":"Mässing, kemiskt förnicklad","sort_order":1},{"param_key":"material","code":"G","label":"Rostfritt stål 303 (bara M3)","sort_order":2},{"param_key":"seal","code":"S","label":"Tätningsmedel på R-gängan","sort_order":0},{"param_key":"seal","code":"P","label":"Plantätning på R-gängan (face seal)","sort_order":1},{"param_key":"button","code":"1","label":"Oval frigöringsknapp (ø3,2, ø4, ø6; standard är rund)","sort_order":0}]'::jsonb)
